package vn.hust.restaurant.view;
import java.awt.*;import java.awt.event.*;import java.math.*;import java.time.*;import java.time.format.*;import java.util.concurrent.Callable;import javax.swing.*;import javax.swing.table.*;
public final class Ui{private Ui(){}public static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");public static final DateTimeFormatter D=DateTimeFormatter.ofPattern("yyyy-MM-dd");
 public static void error(Component p,Throwable e){e.printStackTrace();String m=e.getMessage();if(m==null&&e.getCause()!=null)m=e.getCause().getMessage();JOptionPane.showMessageDialog(p,m==null?e.toString():m,"Lỗi",JOptionPane.ERROR_MESSAGE);}public static void info(Component p,String m){JOptionPane.showMessageDialog(p,m,"Thông báo",JOptionPane.INFORMATION_MESSAGE);}public static boolean confirm(Component p,String m){return JOptionPane.showConfirmDialog(p,m,"Xác nhận",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
 public static DefaultTableModel model(String...c){return new DefaultTableModel(c,0){public boolean isCellEditable(int r,int c){return false;}};}public static JPanel toolbar(Component...cs){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT));for(Component c:cs)p.add(c);return p;}public static BigDecimal dec(String s){return new BigDecimal(s.trim().replace(",","."));}public static int integer(String s){return Integer.parseInt(s.trim());}public static LocalDate date(String s){return LocalDate.parse(s.trim(),D);}public static LocalDateTime dateTime(String s){return LocalDateTime.parse(s.trim(),DT);}public static void width(JTable t,int...w){for(int i=0;i<w.length&&i<t.getColumnCount();i++)t.getColumnModel().getColumn(i).setPreferredWidth(w[i]);}
 public static <T>T call(Component p,Callable<T>c){try{return c.call();}catch(Exception e){error(p,e);return null;}}public static void run(Component p,ThrowingRunnable r){try{r.run();}catch(Exception e){error(p,e);}}@FunctionalInterface public interface ThrowingRunnable{void run()throws Exception;}
 public static JTextField field(String value,int cols){return new JTextField(value==null?"":value,cols);}public static String ask(Component p,String title,String label,String value){JTextField f=field(value,20);int x=JOptionPane.showConfirmDialog(p,new Object[]{label,f},title,JOptionPane.OK_CANCEL_OPTION);return x==JOptionPane.OK_OPTION?f.getText():null;}
}
